-- Hosbah: one firing of a schedule. started_at is when it fired (the feed's order); operation_id
-- is its app.exec operation (null for a skipped run, or one that failed before anything was
-- queued). output is the tail (64 KiB) of what the command printed, SEALED with the team's DEK and
-- bound to this run ('' = none) — never plaintext. The scheduler keeps the newest 200 runs of a
-- schedule. Rows go with their schedule (and so their app).
ALTER TABLE schedule_runs ADD CONSTRAINT schedule_runs_trigger_check CHECK (trigger IN ('schedule', 'manual'));
ALTER TABLE schedule_runs ADD CONSTRAINT schedule_runs_status_check CHECK (status IN ('queued', 'running', 'succeeded', 'failed', 'timeout', 'skipped'));
CREATE INDEX schedule_runs_schedule_idx ON schedule_runs (schedule_id, started_at DESC, id DESC);
CREATE INDEX schedule_runs_active_idx ON schedule_runs (schedule_id) WHERE status IN ('queued', 'running');
CREATE UNIQUE INDEX schedule_runs_operation_key ON schedule_runs (operation_id) WHERE operation_id IS NOT NULL;
CREATE INDEX schedule_runs_team_idx ON schedule_runs (team_id);
